class Solution {
    pair<int, int> farthest(int start, const vector<vector<int>>& graph) {
        queue<int> q;
        vector<int> dist(graph.size(), -1);
        q.push(start);
        dist[start] = 0;
        pair<int, int> best = {start, 0};
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (dist[u] > best.second) {
                best = {u, dist[u]};
            }
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return best;
    }

public:
    int treeDiameter(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> graph(n);
        for (const auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }
        int end = farthest(0, graph).first;
        return farthest(end, graph).second;
    }
};
